"""0.12 real local HTTP contract, permission, transaction and form regressions."""
for tab in ['circles','bounties','reviews']:
    response=admin.get(base+'/admin/index.php',params={'tab':tab});check('0.12 admin '+tab,response.status_code==200,response.text[-200:])
    response=user.get(base+'/admin/index.php',params={'tab':tab});check('0.12 admin denies ordinary user '+tab,response.status_code==403)
for asset in ['spring.js','interactions.js','interactions.css','community.css']:
    response=guest.get(base+'/assets/'+asset);check('0.12 asset '+asset,response.status_code==200 and len(response.content)>500)
save_group('community',circles_enabled='1',bounties_enabled='1',bounty_max='1000')
save_group('commerce',reviews_enabled='1',reviews_review='1',invitation_products_enabled='1')
