expect_post(admin,'admin_entity',entity='categories',name='HTTP restricted circle',kind='thread',is_circle='1',access_level='members',post_level='members',join_currency='points',join_price='40',join_days='7',join_open='1')
circle=db_one('SELECT id FROM cy_categories WHERE name=?',('HTTP restricted circle',))['id']
private_post=create_content(kind='thread',category_id=circle,title='PRIVATE-CIRCLE-TITLE',body='PRIVATE-CIRCLE-BODY')
check('circle directory is available',guest.get(base+'/index.php?r=circles').status_code==200)
check('circle public introduction excludes restricted posts','PRIVATE-CIRCLE-TITLE' not in guest.get(base+f'/index.php?r=circle&id={circle}').text)
check('private circle direct URL denied',guest.get(base+f'/index.php?r=article&id={private_post}').status_code==403)
check('private circle search excludes title','PRIVATE-CIRCLE-TITLE' not in guest.get(base+'/index.php?r=search&q=PRIVATE-CIRCLE').text)
intent=os.urandom(16).hex();before=db_one('SELECT points FROM cy_users WHERE id=?',(uid,))['points']
expect_post(user,'buy',kind='circle',item_id=circle,intent=intent);expect_post(user,'buy',kind='circle',item_id=circle,intent=intent)
order=db_one("SELECT * FROM cy_orders WHERE user_id=? AND item_id=? AND kind='circle'",(uid,circle))
check('circle HTTP retries debit exactly once',db_one('SELECT points FROM cy_users WHERE id=?',(uid,))['points']==before-40)
check('joined circle exposes authorized body','PRIVATE-CIRCLE-BODY' in user.get(base+f'/index.php?r=article&id={private_post}').text)
expect_post(admin,'admin_circle_member',category_id=circle,user_id=uid,blocked='1')
check('manual suspension revokes direct access',user.get(base+f'/index.php?r=article&id={private_post}').status_code==403)
expect_post(admin,'admin_circle_member',category_id=circle,user_id=uid,blocked='0')
check('removing suspension restores paid term',user.get(base+f'/index.php?r=article&id={private_post}').status_code==200)
expect_post(user,'refund',order_id=order['id'],reason='HTTP circle refund')
expect_post(admin,'admin_refund',id=order['id'],decision='approve',current_password='TestPassword!2026')
check('refunded circle loses access',user.get(base+f'/index.php?r=article&id={private_post}').status_code==403)
check('circle refund returns original points',db_one('SELECT points FROM cy_users WHERE id=?',(uid,))['points']==before)
expect_post(admin,'admin_entity',404,entity='categories',id=999999,name='No phantom category',kind='thread')
multi=create_content(kind='thread',thread_mode='poll',title='HTTP multi choice',poll_question='Pick two',poll_options='First\nSecond\nThird',poll_max_choices='2',poll_results='after_vote')
choices=[r['id'] for r in conn.execute('SELECT id FROM cy_poll_options WHERE content_id=? ORDER BY id',(multi,))]
form=html(user,f'/index.php?r=article&id={multi}').select_one('.poll-form')
check('multiple selection uses real native checkboxes',len(form.select('input[type=checkbox][name="option_ids[]"]'))==3)
r=user.post(base+'/action.php',data={'csrf':csrf(user),'action':'poll_vote','content_id':multi,'option_ids[]':choices[:2]},headers={'Accept':'application/json'});check('PHP array ballot accepted through real HTTP',r.status_code==200,r.text)
r=user.post(base+'/action.php',data={'csrf':csrf(user),'action':'poll_vote','content_id':multi,'option_ids[]':list(reversed(choices[:2]))},headers={'Accept':'application/json'});check('reordered ballot retry remains idempotent',r.status_code==200,r.text)
check('one ballot and two choices stored',db_one('SELECT COUNT(*) n FROM cy_poll_votes WHERE content_id=?',(multi,))['n']==1 and db_one('SELECT COUNT(*) n FROM cy_poll_choices c JOIN cy_poll_votes v ON v.id=c.vote_id WHERE v.content_id=?',(multi,))['n']==2)
r=user.post(base+'/action.php',data={'csrf':csrf(user),'action':'poll_vote','content_id':multi,'option_ids[bad][nested]':'1'},headers={'Accept':'application/json'});check('nested ballot values rejected',r.status_code==400,r.text)
