check('accepted bounty pays answerer only once',db_one('SELECT points FROM cy_users WHERE id=?',(uid,))['points']==old+60)
check('awarded bounty rendered',db_one('SELECT status FROM cy_bounties WHERE content_id=?',(question,))['status']=='awarded' and bool(html(user,f'/index.php?r=article&id={question}').select('.bounty-panel')))
