# Isolated SQL fixtures exercise pagination beyond the first page; no real users are created.
fixture_hash=db_one('SELECT password_hash FROM cy_users WHERE id=1')['password_hash']
for number in range(50):
    username='pager012_'+str(number)
    cursor=conn.execute('INSERT INTO cy_users(username,email,password_hash,display_name,bio,created_at) VALUES (?,?,?,?,?,?)',(username,username+'@example.test',fixture_hash,username,'',int(time.time())))
    conn.execute('INSERT INTO cy_circle_members(category_id,user_id,granted_until,blocked,updated_at) VALUES (?,?,?,?,?)',(circle,cursor.lastrowid,int(time.time())+86400,0,int(time.time())+100+number))
conn.commit()
page1=html(admin,f'/admin/index.php?tab=circles&category_id={circle}')
link=page1.select_one('a[href*="member_page=2"]')
check('manual member listing exposes next page after fifty rows',bool(link))
check('manual member pagination preserves selected circle',bool(link) and f'category_id={circle}' in link['href'])
page2=html(admin,f'/admin/index.php?tab=circles&category_id={circle}&member_page=2')
check('second manual member page contains remaining row',len(page2.select('section.panel.section tbody tr'))==1)
